    /// Regression for the confirmed defect where `reconfirm`'s atomic
    /// `UPDATE` guarded only on `retired_at IS NULL`: `Superseded` leaves
    /// `retired_at` NULL by design (ADR-0113 decision 1), so a statement that
    /// had already been explicitly replaced could still silently acquire a
    /// fresh `confirmed_at` and an audit row. record -> activate -> supersede
    /// -> reconfirm must now return `None` and leave both the clock and the
    /// audit chain untouched.
    #[tokio::test]
    async fn reconfirm_refuses_a_superseded_statement_and_leaves_its_clock_and_audit_chain_untouched(
    ) {
        let Some(store) = store().await else {
            println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
            return;
        };
        let (tenant_id, repository_id) = unique_scope("reconfirm-superseded");
        let recorded = store
            .record(RecordKnowledgeRequest {
                tenant_id: tenant_id.clone(),
                repository_id: repository_id.clone(),
                content: "the guidance about to be replaced".to_string(),
                source_ref: None,
                recorded_by: None,
                reach_node_ids: Vec::new(),
                reach_goal_id: None,
                half_life_hours: 24.0,
                embedding: None,
            })
            .await
            .unwrap();
        store
            .activate(
                &tenant_id,
                &repository_id,
                &recorded.knowledge_id,
                "human:reviewer-1",
                None,
                SystemTime::now(),
            )
            .await
            .unwrap();
        let confirmed_at_before_supersede = store
            .history(&tenant_id, &repository_id, 10)
            .await
            .unwrap()
            .into_iter()
            .find(|entry| entry.knowledge_id == recorded.knowledge_id)
            .unwrap()
            .confirmed_at;

        store
            .supersede(
                SupersedeKnowledgeRequest {
                    tenant_id: tenant_id.clone(),
                    repository_id: repository_id.clone(),
                    knowledge_id: recorded.knowledge_id.clone(),
                    new_content: "the corrected guidance".to_string(),
                    new_source_ref: None,
                    new_recorded_by: None,
                    new_reach_node_ids: Vec::new(),
                    new_reach_goal_id: None,
                    new_half_life_hours: 24.0,
                    authorized_by: "human:reviewer-1".to_string(),
                    reason: "the replacement corrects stale guidance".to_string(),
                },
                SystemTime::now(),
            )
            .await
            .unwrap();

        let attempt = store
            .reconfirm(
                &tenant_id,
                &repository_id,
                &recorded.knowledge_id,
                "evidence:seen-again",
                "node:reviewer",
                SystemTime::now(),
            )
            .await
            .unwrap();
        assert_eq!(
            attempt, None,
            "a superseded statement must not be reconfirmable"
        );

        let history = store.history(&tenant_id, &repository_id, 10).await.unwrap();
        let superseded_entry = history
            .iter()
            .find(|entry| entry.knowledge_id == recorded.knowledge_id)
            .unwrap();
        assert_eq!(
            superseded_entry.lifecycle_state,
            KnowledgeLifecycleState::Superseded
        );
        assert_eq!(
            superseded_entry.confirmed_at, confirmed_at_before_supersede,
            "the refused reconfirmation must not refresh confirmed_at"
        );
        assert_eq!(
            superseded_entry.last_reconfirmed_at, None,
            "the refused reconfirmation must not leave an audit row"
        );
        assert_eq!(superseded_entry.last_reconfirmed_by, None);
        assert_eq!(superseded_entry.last_reconfirmation_evidence_ref, None);
    }

    #[tokio::test]
    async fn recall_ranks_by_pgvector_similarity_when_an_embedding_is_supplied() {
        let Some(store) = store().await else {
            println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
            return;
        };
        let (tenant_id, repository_id) = unique_scope("semantic");
        let model = "test-embedder";
        let closest = store
            .record(RecordKnowledgeRequest {
                tenant_id: tenant_id.clone(),
                repository_id: repository_id.clone(),
                content: "closest match".to_string(),
                source_ref: None,
                recorded_by: None,
                reach_node_ids: Vec::new(),
                reach_goal_id: None,
                half_life_hours: 720.0,
                embedding: Some((model.to_string(), vec![1.0; 768])),
            })
            .await
            .unwrap();
        let farthest = store
            .record(RecordKnowledgeRequest {
                tenant_id: tenant_id.clone(),
                repository_id: repository_id.clone(),
                content: "farthest match".to_string(),
                source_ref: None,
                recorded_by: None,
                reach_node_ids: Vec::new(),
                reach_goal_id: None,
                half_life_hours: 720.0,
                embedding: Some((model.to_string(), {
                    let mut v = vec![1.0; 768];
                    v[0] = -1.0;
                    v
                })),
            })
            .await
            .unwrap();
        for knowledge_id in [&closest.knowledge_id, &farthest.knowledge_id] {
            store
                .activate(
                    &tenant_id,
                    &repository_id,
                    knowledge_id,
                    "human:reviewer-1",
                    None,
                    SystemTime::now(),
                )
                .await
                .unwrap();
        }

        let recalled = store
            .recall(
                &tenant_id,
                &repository_id,
                Some((model, vec![1.0; 768])),
                10,
            )
            .await
            .unwrap();

        assert!(recalled.ranked_by_similarity);
        assert_eq!(recalled.entries.len(), 2);
        assert_eq!(recalled.entries[0].knowledge_id, closest.knowledge_id);
    }

    #[tokio::test]
    async fn recall_under_a_model_nothing_was_embedded_with_still_returns_by_recency() {
        let Some(store) = store().await else {
            println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
            return;
        };
        let (tenant_id, repository_id) = unique_scope("no-model-match");
        store
            .record(RecordKnowledgeRequest {
                tenant_id: tenant_id.clone(),
                repository_id: repository_id.clone(),
                content: "embedded under a different model".to_string(),
                source_ref: None,
                recorded_by: None,
                reach_node_ids: Vec::new(),
                reach_goal_id: None,
                half_life_hours: 720.0,
                embedding: Some(("other-model".to_string(), vec![0.5; 768])),
            })
            .await
            .unwrap();

        let recalled = store
            .recall(
                &tenant_id,
                &repository_id,
                Some(("nomic-embed-text", vec![0.5; 768])),
                10,
            )
            .await
            .unwrap();

        // The JOIN on model finds nothing, so the semantic path legitimately
        // returns zero rows -- this is honest degradation (ranked_by_similarity
        // stays true because a query WAS supplied), not a silent fallback that
        // would hide the mismatch.
        assert_eq!(recalled.entries.len(), 0);
    }

    #[tokio::test]
    async fn active_pages_use_confirmed_at_and_knowledge_id_without_crossing_tenant_or_retired_rows(
    ) {
        let Some(store) = store().await else {
            println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
            return;
        };
        let (tenant_id, repository_id) = unique_scope("active-page");
        let migration = store
            .client
            .query_one(
                "SELECT EXISTS (\
                     SELECT 1 FROM ackplane_schema_migrations WHERE migration_key = $1\
                 ) AS migration_recorded, \
                 to_regclass('public.knowledge_active_page_order') IS NOT NULL AS index_created",
                &[&crate::migration_lock::key::KNOWLEDGE_ACTIVE_PAGE_INDEX],
            )
            .await
            .expect("active-page index migration is registered and applied");
        assert_eq!(
            (migration.get::<_, bool>(0), migration.get::<_, bool>(1)),
            (true, true),
            "active knowledge pages need their partial recency index"
        );
        let confirmed_at = [
            SystemTime::UNIX_EPOCH + std::time::Duration::from_secs(400),
            SystemTime::UNIX_EPOCH + std::time::Duration::from_secs(300),
            SystemTime::UNIX_EPOCH + std::time::Duration::from_secs(200),
        ];
        for (knowledge_id, timestamp) in [
            ("knowledge:newest", confirmed_at[0]),
            ("knowledge:a", confirmed_at[1]),
            ("knowledge:b", confirmed_at[1]),
            ("knowledge:older", confirmed_at[2]),
            ("knowledge:retired", confirmed_at[0]),
        ] {
            store
                .client
                .execute(
                    "INSERT INTO knowledge \
                     (tenant_id, repository_id, knowledge_id, content, source_ref, half_life_hours, confirmed_at) \
                     VALUES ($1, $2, $3, $4, NULL, $5, $6)",
                    &[
                        &tenant_id,
                        &repository_id,
                        &knowledge_id,
                        &format!("content for {knowledge_id}"),
                        &720.0_f64,
                        &timestamp,
                    ],
                )
                .await
                .expect("insert deterministic active-page fixture");
        }
        store
            .retire(
                &tenant_id,
                &repository_id,
                "knowledge:retired",
                "superseded",
                "node:reviewer",
            )
            .await
            .expect("retire excluded fixture");
        let (other_tenant_id, _) = unique_scope("active-page-other");
        store
            .client
            .execute(
                "INSERT INTO knowledge \
                 (tenant_id, repository_id, knowledge_id, content, source_ref, half_life_hours, confirmed_at) \
                 VALUES ($1, $2, $3, $4, NULL, $5, $6)",
                &[
                    &other_tenant_id,
                    &repository_id,
                    &"knowledge:foreign",
                    &"foreign tenant fixture",
                    &720.0_f64,
                    &confirmed_at[0],
                ],
            )
            .await
            .expect("insert tenant-isolation fixture");

        let first = store
            .active_page(&tenant_id, &repository_id, None, 2)
            .await
            .expect("read first active knowledge page");
        assert_eq!(
            first
                .entries
                .iter()
                .map(|entry| entry.knowledge_id.as_str())
                .collect::<Vec<_>>(),
            vec!["knowledge:newest", "knowledge:a"]
        );
        assert_eq!(
            first.next_before,
            Some(ActiveKnowledgeCursor {
                confirmed_at: confirmed_at[1],
                knowledge_id: "knowledge:a".to_string(),
            })
        );

        let second = store
            .active_page(&tenant_id, &repository_id, first.next_before.as_ref(), 2)
            .await
            .expect("read second active knowledge page");
        assert_eq!(
            second
                .entries
                .iter()
                .map(|entry| entry.knowledge_id.as_str())
                .collect::<Vec<_>>(),
            vec!["knowledge:b", "knowledge:older"]
        );
        assert_eq!(second.next_before, None);

        let foreign = store
            .active_page(&other_tenant_id, &repository_id, None, 2)
            .await
            .expect("read foreign tenant page");
        assert_eq!(
            foreign
                .entries
                .iter()
                .map(|entry| entry.knowledge_id.as_str())
                .collect::<Vec<_>>(),
            vec!["knowledge:foreign"]
        );
    }
